<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';$u=require_login();$pdo=db();$q=$pdo->prepare("SELECT COUNT(*) FROM trade_requests WHERE (buyer_id=? OR seller_id=?) AND status='completed'");$q->execute([$u['id'],$u['id']]);$trades=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COALESCE(AVG(rating),0) FROM reviews WHERE reviewed_user_id=?');$q->execute([$u['id']]);$rating=(float)$q->fetchColumn();$q=$pdo->prepare("SELECT *,(SELECT image_path FROM listing_images WHERE listing_id=listings.id ORDER BY id LIMIT 1) image_path FROM listings WHERE user_id=? AND status<>'removed' ORDER BY created_at DESC");$q->execute([$u['id']]);$own=$q->fetchAll();$r=$pdo->prepare('SELECT r.*,u.name reviewer FROM reviews r JOIN users u ON u.id=r.reviewer_id WHERE r.reviewed_user_id=? ORDER BY r.created_at DESC');$r->execute([$u['id']]);$reviews=$r->fetchAll();$pageTitle='Profile';include __DIR__.'/includes/header.php';?><div class="section-head"><div><h2><?=e($u['name'])?></h2><p><?=e($u['location'] ?: 'Location not set')?> · Member since <?=date('M Y',strtotime($u['created_at']))?></p></div></div><div class="stats"><div class="stat"><span class="muted">Rating</span><strong><?=number_format($rating,1)?></strong></div><div class="stat"><span class="muted">Completed trades</span><strong><?=$trades?></strong></div><div class="stat"><span class="muted">Active listings</span><strong><?=count($own)?></strong></div><div class="stat"><span class="muted">Reviews</span><strong><?=count($reviews)?></strong></div></div><div class="section-head"><div><h2>Your listings</h2></div><a class="btn btn-sm" href="/create-listing.php">Sell item</a></div><div class="grid"><?php foreach($own as $l):?><a class="card" href="/listing.php?id=<?=$l['id']?>"><div class="product-img placeholder"><?php if($l['image_path']):?><img class="product-img" src="<?=e($l['image_path'])?>"><?php else:?>RADIUS<?php endif;?></div><div class="card-body"><span class="badge <?=e(trust_class($l['trust_status']??''))?>"><?=e(trust_label($l['trust_status']??''))?></span><h3><?=e($l['title'])?></h3><strong><?=money($l['price'])?></strong><div class="muted">Status: <?=e($l['status'])?></div></div></a><?php endforeach;?></div><div class="section-head"><h2>Reviews</h2></div><?php foreach($reviews as $rv):?><div class="card card-body" style="margin-bottom:10px"><strong><?=e($rv['reviewer'])?> · <?=$rv['rating']?>/5</strong><p><?=e($rv['comment'])?></p></div><?php endforeach;?><?php if(!$reviews):?><div class="empty">No reviews yet.</div><?php endif;?><?php include __DIR__.'/includes/footer.php';?>